from collections import deque

def geodesic_labels(grid, special, seed_colors, tie=special):
    H,W=grid.shape
    # distances per seed color by BFS through special cells; seed at each special cell adjacent to source.
    ds={c:np.full((H,W),999,int) for c in seed_colors}
    for color in seed_colors:
      q=deque()
      for r,c in np.argwhere(grid==special):
       if any(0<=r+dr<H and 0<=c+dc<W and grid[r+dr,c+dc]==color for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)]):
        ds[color][r,c]=1;q.append((r,c))
      while q:
       r,c=q.popleft()
       for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)]:
        rr,cc=r+dr,c+dc
        if 0<=rr<H and 0<=cc<W and grid[rr,cc]==special and ds[color][rr,cc]>ds[color][r,c]+1:
         ds[color][rr,cc]=ds[color][r,c]+1;q.append((rr,cc))
    outpred=grid.copy()
    for r,c in np.argwhere(grid==special):
      vals={color:ds[color][r,c] for color in seed_colors}
      mn=min(vals.values())
      winners=[color for color,v in vals.items() if v==mn]
      outpred[r,c]=winners[0] if len(winners)==1 else tie
    return outpred,ds
